function medianeDeuxTries(a, b) {
  const totalLength = a.length + b.length;
  const midIndex = Math.floor(totalLength / 2);

  // Find the k-th element (0-indexed) in two sorted arrays combined
  function findKthElement(arr1, arr2, k) {
    if (arr1.length === 0) return arr2[k];
    if (arr2.length === 0) return arr1[k];

    // Avoid index out of bounds
    const idx1 = Math.min(k, arr1.length - 1);
    const idx2 = Math.min(k, arr2.length - 1);

    if (idx1 < idx2) {
      // If element at idx1 is smaller than element at idx2, 
      // we can discard the first idx1+1 elements of arr1
      return findKthElement(arr1.slice(idx1 + 1), arr2, k - idx1 - 1);
    } else if (idx1 > idx2) {
      // If element at idx2 is smaller than element at idx1, 
      // we can discard the first idx2+1 elements of arr2
      return findKthElement(arr1, arr2.slice(idx2 + 1), k - idx2 - 1);
    } else {
      // Elements are equal or both indices are out of bounds (k is too large)
      if (idx1 === k && idx2 === k) {
        return Math.min(arr1[idx1], arr2[idx2]);
      } else if (idx1 < k || idx2 < k) {
        // This case should be handled by the recursive calls above, but as a fallback:
        return findKthElement(arr1.slice(idx1 + 1), arr2.slice(idx2 + 1), k - Math.max(idx1, idx2) - 1);
      } else {
        // Both indices are out of bounds (k is larger than both array lengths)
        return findKthElement([], [], k); 
      }
    }
  }

  const firstHalf = findKthElement(a, b, midIndex);

  if (totalLength % 2 === 0) {
    // Even number of elements: average of the two middle elements
    const secondHalf = findKthElement(a, b, midIndex + 1);
    return (firstHalf + secondHalf) / 2;
  } else {
    // Odd number of elements: the single middle element
    return firstHalf;
  }
}
